// 离线数值扫描：为 CR3BP 实验室确定预设初值与自检阈值（与页面内核同构，仅用于开发期调参）
const MU = 0.0121505856;
const RE = 6378.137 / 384400, RM = 1737.4 / 384400;

function omega(x, y) {
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  return 0.5 * (x * x + y * y) + (1 - MU) / r1 + MU / r2;
}
function f(s) {
  const [x, y, vx, vy] = s;
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  const r1c = r1 * r1 * r1, r2c = r2 * r2 * r2;
  return [vx, vy,
    2 * vy + x - (1 - MU) * (x + MU) / r1c - MU * (x - 1 + MU) / r2c,
    -2 * vx + y - (1 - MU) * y / r1c - MU * y / r2c];
}
function jacobi(s) { return 2 * omega(s[0], s[1]) - (s[2] * s[2] + s[3] * s[3]); }
const add = (s, k, h) => [s[0] + h * k[0], s[1] + h * k[1], s[2] + h * k[2], s[3] + h * k[3]];
function rk4(s, dt) {
  const k1 = f(s), k2 = f(add(s, k1, dt / 2)), k3 = f(add(s, k2, dt / 2)), k4 = f(add(s, k3, dt));
  return [s[0] + dt / 6 * (k1[0] + 2 * k2[0] + 2 * k3[0] + k4[0]),
          s[1] + dt / 6 * (k1[1] + 2 * k2[1] + 2 * k3[1] + k4[1]),
          s[2] + dt / 6 * (k1[2] + 2 * k2[2] + 2 * k3[2] + k4[2]),
          s[3] + dt / 6 * (k1[3] + 2 * k2[3] + 2 * k3[3] + k4[3])];
}
const SQ3_6 = Math.sqrt(3) / 6;
function gl4(s, dt) {
  const A = [[0.25, 0.25 - SQ3_6], [0.25 + SQ3_6, 0.25]];
  let k1 = f(s), k2 = f(s);
  let Y1, Y2, n1, n2, it = 0;
  for (; it < 24; it++) {
    Y1 = [0, 0, 0, 0], Y2 = [0, 0, 0, 0];
    for (let j = 0; j < 4; j++) {
      Y1[j] = s[j] + dt * (A[0][0] * k1[j] + A[0][1] * k2[j]);
      Y2[j] = s[j] + dt * (A[1][0] * k1[j] + A[1][1] * k2[j]);
    }
    n1 = f(Y1); n2 = f(Y2);
    let d = 0;
    for (let j = 0; j < 4; j++) d = Math.max(d, Math.abs(n1[j] - k1[j]), Math.abs(n2[j] - k2[j]));
    k1 = n1; k2 = n2;
    if (d < 1e-13) break;
  }
  return [s[0] + dt * 0.5 * (k1[0] + k2[0]), s[1] + dt * 0.5 * (k1[1] + k2[1]),
          s[2] + dt * 0.5 * (k1[2] + k2[2]), s[3] + dt * 0.5 * (k1[3] + k2[3])];
}
function integrate(s0, tEnd, dt, method = rk4, stop) {
  let s = s0.slice(), n = Math.max(1, Math.round(tEnd / dt));
  for (let i = 0; i < n; i++) {
    s = method(s, dt);
    if (!s.every(Number.isFinite)) return { s, hit: 'nan', i };
    if (stop && stop(s)) return { s, hit: stop(s), i };
  }
  return { s, hit: null, i: n };
}
// ---- 拉格朗日点 ----
function collinear(lo, hi) {
  const g = x => x - (1 - MU) * (x + MU) / Math.abs(x + MU) ** 3 - MU * (x - 1 + MU) / Math.abs(x - 1 + MU) ** 3;
  for (let i = 0; i < 200; i++) {
    const m = (lo + hi) / 2;
    (g(lo) * g(m) <= 0) ? hi = m : lo = m;
  }
  return (lo + hi) / 2;
}
const L1 = collinear(-MU + 1e-9, 1 - MU - 1e-9), L2 = collinear(1 - MU + 1e-9, 2), L3 = collinear(-2, -MU - 1e-9);
const L4 = [0.5 - MU, Math.sqrt(3) / 2], L5 = [0.5 - MU, -Math.sqrt(3) / 2];
const Ls = { L1: [L1, 0], L2: [L2, 0], L3: [L3, 0], L4, L5 };
console.log('== 拉格朗日点 ==');
let maxRes = 0;
for (const [k, p] of Object.entries(Ls)) {
  const a = f([p[0], p[1], 0, 0]);
  const res = Math.hypot(a[2], a[3]);
  maxRes = Math.max(maxRes, res);
  console.log(`${k}: (${p[0].toFixed(9)}, ${p[1].toFixed(6)})  |a|=${res.toExponential(3)}  C=${(2 * omega(p[0], p[1])).toFixed(6)}`);
}
console.log('max residual:', maxRes.toExponential(3));

// ---- 收敛阶 & 守恒（用 L4 扰动 IC）----
const IC_T = [L4[0] + 0.02, L4[1] + 0.01, 0, 0];
function runErr(dt, tEnd, method) {
  const ref = integrate(IC_T, tEnd, dt / 16, method).s;
  const y = integrate(IC_T, tEnd, dt, method).s;
  return Math.hypot(y[0] - ref[0], y[1] - ref[1]);
}
const e1 = runErr(0.02, 2), e2 = runErr(0.01, 2), e3 = runErr(0.005, 2);
console.log('\n== RK4 收敛阶(t=2): err=', e1.toExponential(3), e2.toExponential(3), e3.toExponential(3),
  ' p12=', Math.log2(e1 / e2).toFixed(3), ' p23=', Math.log2(e2 / e3).toFixed(3));
function drift(tEnd, dt, method) {
  const r = integrate(IC_T, tEnd, dt, method, s => Math.abs(s[0]) > 8 ? 'far' : null);
  if (r.hit) return { hit: r.hit };
  const C0 = jacobi(IC_T);
  // 逐段重扫取最大漂移
  let s = IC_T.slice(), max = 0;
  for (let i = 0; i < tEnd / dt; i++) { s = method(s, dt); max = Math.max(max, Math.abs(jacobi(s) - C0)); }
  return { max };
}
console.log('RK4  t=60 dt=0.005 max|dC|:', JSON.stringify(drift(60, 0.005, rk4)));
console.log('GL4  t=60 dt=0.005 max|dC|:', JSON.stringify(drift(60, 0.005, gl4)));
console.log('GL4  t=200 dt=0.005 max|dC|:', JSON.stringify(drift(200, 0.005, gl4)));
console.log('RK4  t=200 dt=0.005 max|dC|:', JSON.stringify(drift(200, 0.005, rk4)));
const r4 = integrate(IC_T, 4, 0.005, rk4).s, g4 = integrate(IC_T, 4, 0.005, gl4).s;
console.log('RK4 vs GL4 t=4 dt=0.005 pos diff:', Math.hypot(r4[0] - g4[0], r4[1] - g4[1]).toExponential(3));

// ---- 预设扫描 ----
const CL1 = 2 * omega(L1, 0);
console.log('\n== 预设 ==');
