const Ein = s => { const vix = s[2] - s[1], viy = s[3] + s[0]; return 0.5 * (vix * vix + viy * viy) - (1 - MU) / Math.hypot(s[0] + MU, s[1]) - MU / Math.hypot(s[0] - 1 + MU, s[1]); };
const jac = s => 2 * omega(s[0], s[1]) - (s[2] ** 2 + s[3] ** 2);

const cands = {
