  B: [1.078, 0.338, -0.177, -0.468],   // 候选8：近距
  C: [0.740, -0.247, 0.233, 0.261],    // 候选13：左下接近
};
for (const [k, s0] of Object.entries(cands)) {
  console.log(`\n=== 候选 ${k}: (${s0.join(', ')})  C=${jac(s0).toFixed(4)} E_in0=${Ein(s0).toFixed(3)}`);
  for (const [nm, m] of [['RK4', rk4], ['GL4', gl4]]) {
    for (const dt of [0.002, 0.005, 0.01]) {
      let s = s0.slice(), minM = 9, tM = 0, tEsc = null, E1 = 0;
