// 扫描第二轮：L4 有界扰动、守恒误差（平滑轨道）、引力辅助
const MU = 0.0121505856;
const RE = 6378.137 / 384400, RM = 1737.4 / 384400;
function omega(x, y) {
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  return 0.5 * (x * x + y * y) + (1 - MU) / r1 + MU / r2;
}
function f(s) {
  const [x, y, vx, vy] = s;
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  const r1c = r1 * r1 * r1, r2c = r2 * r2 * r2;
  return [vx, vy,
    2 * vy + x - (1 - MU) * (x + MU) / r1c - MU * (x - 1 + MU) / r2c,
    -2 * vx + y - (1 - MU) * y / r1c - MU * y / r2c];
}
function jacobi(s) { return 2 * omega(s[0], s[1]) - (s[2] * s[2] + s[3] * s[3]); }
const add = (s, k, h) => [s[0] + h * k[0], s[1] + h * k[1], s[2] + h * k[2], s[3] + h * k[3]];
function rk4(s, dt) {
  const k1 = f(s), k2 = f(add(s, k1, dt / 2)), k3 = f(add(s, k2, dt / 2)), k4 = f(add(s, k3, dt));
  return [s[0] + dt / 6 * (k1[0] + 2 * k2[0] + 2 * k3[0] + k4[0]),
          s[1] + dt / 6 * (k1[1] + 2 * k2[1] + 2 * k3[1] + k4[1]),
          s[2] + dt / 6 * (k1[2] + 2 * k2[2] + 2 * k3[2] + k4[2]),
          s[3] + dt / 6 * (k1[3] + 2 * k2[3] + 2 * k3[3] + k4[3])];
}
const SQ3_6 = Math.sqrt(3) / 6;
function gl4(s, dt) {
  const A = [[0.25, 0.25 - SQ3_6], [0.25 + SQ3_6, 0.25]];
  let k1 = f(s), k2 = f(s), it = 0;
  for (; it < 24; it++) {
    const Y1 = [0, 0, 0, 0], Y2 = [0, 0, 0, 0];
    for (let j = 0; j < 4; j++) {
      Y1[j] = s[j] + dt * (A[0][0] * k1[j] + A[0][1] * k2[j]);
      Y2[j] = s[j] + dt * (A[1][0] * k1[j] + A[1][1] * k2[j]);
    }
    const n1 = f(Y1), n2 = f(Y2);
    let d = 0;
    for (let j = 0; j < 4; j++) d = Math.max(d, Math.abs(n1[j] - k1[j]), Math.abs(n2[j] - k2[j]));
    k1 = n1; k2 = n2;
    if (d < 1e-13) break;
  }
  return [s[0] + dt * 0.5 * (k1[0] + k2[0]), s[1] + dt * 0.5 * (k1[1] + k2[1]),
          s[2] + dt * 0.5 * (k1[2] + k2[2]), s[3] + dt * 0.5 * (k1[3] + k2[3])];
}
function drift(s0, tEnd, dt, method) {
  const C0 = jacobi(s0);
  let s = s0.slice(), max = 0, its = 0;
  for (let i = 0; i < tEnd / dt; i++) { s = method(s, dt); max = Math.max(max, Math.abs(jacobi(s) - C0)); }
  return { max, s };
}
// 平滑有界轨道（绕地 r=0.15 圆）
const IC_E = [-MU - 0.15, 0, 0, 2.728410];
console.log('== 守恒（绕地轨道，平滑）==');
for (const dt of [0.005, 0.01, 0.02]) {
  const a = drift(IC_E, 60, dt, rk4), b = drift(IC_E, 60, dt, gl4);
  const a2 = drift(IC_E, 300, dt, rk4), b2 = drift(IC_E, 300, dt, gl4);
  console.log(`dt=${dt}: RK4 t=60 ${a.max.toExponential(2)} t=300 ${a2.max.toExponential(2)} | GL4 t=60 ${b.max.toExponential(2)} t=300 ${b2.max.toExponential(2)}`);
}
// L4 有界扰动扫描
console.log('\n== L4 扰动（t=150，找有界 tadpole）==');
const L4 = [0.5 - MU, Math.sqrt(3) / 2];
for (const off of [[0.01, 0], [0.02, 0], [0.03, 0], [0, 0.02], [0.02, 0.02], [-0.02, 0], [0.05, 0]]) {
  const s0 = [L4[0] + off[0], L4[1] + off[1], 0, 0];
  let s = s0.slice(), minD = 9, maxD = 0, maxAbs = 0, ok = true;
  for (let i = 0; i < 150 / 0.005; i++) {
    s = gl4(s, 0.005);
    const d = Math.hypot(s[0] - L4[0], s[1] - L4[1]);
    minD = Math.min(minD, d); maxD = Math.max(maxD, d); maxAbs = Math.max(maxAbs, Math.abs(s[0]), Math.abs(s[1]));
    if (!Number.isFinite(s[0])) { ok = false; break; }
  }
  console.log(`off=(${off}) -> d(L4)∈[${minD.toFixed(3)},${maxD.toFixed(3)}] max|x|,|y|=${maxAbs.toFixed(3)} ok=${ok}`);
}
// 引力辅助：固定起点(地球附近)，扫速度方向和大小
console.log('\n== 引力辅助扫描 ==');
const CL1 = 2 * omega(0.836915126, 0);
const cands = [];
const r0 = 0.3;
const starts = [[-MU - r0, 0], [-MU + r0, 0], [-MU, r0], [-MU, -r0]];
for (const [x0, y0] of starts) {
  for (let ith = 0; ith < 96; ith++) {
    const th = ith * Math.PI / 48;
    for (const v of [1.3, 1.5, 1.7, 1.9, 2.1]) {
      const s0 = [x0, y0, v * Math.cos(th), v * Math.sin(th)];
      if (jacobi(s0) > CL1) continue;
      let s = s0.slice(), minM = 1e9, tM = 0, endR = 0;
      for (let i = 0; i < 30 / 0.01; i++) {
        s = rk4(s, 0.01);
        const dM = Math.hypot(s[0] - 1 + MU, s[1]);
        if (dM < minM) { minM = dM; tM = (i + 1) * 0.01; }
        endR = Math.hypot(s[0], s[1]);
        if (!Number.isFinite(s[0]) || endR > 3.5) break;
      }
      if (minM < 0.1 && minM > 0.0046 && endR > 0.8) {
        const Ein0 = 0.5 * (s0[2] * s0[2] + s0[3] * s0[3]) + (s0[2] * (-y0) + s0[3] * x0) + 0.5 * (x0 * x0 + y0 * y0) - omega(x0, y0);
        const vin2x = s[2] - s[1], vin2y = s[3] + s[0];
        const Ein1 = 0.5 * (vin2x * vin2x + vin2y * vin2y) - omega(s[0], s[1]);
        cands.push({ start: `(${x0.toFixed(3)},${y0.toFixed(3)})`, th: th.toFixed(2), v, vx: s0[2].toFixed(3), vy: s0[3].toFixed(3), minM: +minM.toFixed(4), tM, endR: +endR.toFixed(2), dEin: +(Ein1 - Ein0).toFixed(3), C: +jacobi(s0).toFixed(3) });
      }
    }
  }
}
cands.sort((a, b) => b.dEin - a.dEin);
console.log(`共 ${cands.length} 个候选（按惯性系能量增量降序，前 15）:`);
console.table(cands.slice(0, 15));

// 验证引力辅助预设的步长稳健性 + 轨迹形状
const MU = 0.0121505856;
const RM = 1737.4 / 384400, RE = 6378.137 / 384400;
function omega(x, y) {
