// 验证引力辅助预设的步长稳健性 + 轨迹形状
const MU = 0.0121505856;
const RM = 1737.4 / 384400, RE = 6378.137 / 384400;
function omega(x, y) {
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  return 0.5 * (x * x + y * y) + (1 - MU) / r1 + MU / r2;
}
function f(s) {
  const [x, y, vx, vy] = s;
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  const r1c = r1 ** 3, r2c = r2 ** 3;
  return [vx, vy, 2 * vy + x - (1 - MU) * (x + MU) / r1c - MU * (x - 1 + MU) / r2c,
    -2 * vx + y - (1 - MU) * y / r1c - MU * y / r2c];
}
const add = (s, k, h) => [s[0] + h * k[0], s[1] + h * k[1], s[2] + h * k[2], s[3] + h * k[3]];
function rk4(s, dt) {
  const k1 = f(s), k2 = f(add(s, k1, dt / 2)), k3 = f(add(s, k2, dt / 2)), k4 = f(add(s, k3, dt));
  return [0, 1, 2, 3].map(j => s[j] + dt / 6 * (k1[j] + 2 * k2[j] + 2 * k3[j] + k4[j]));
}
const SQ3_6 = Math.sqrt(3) / 6;
function gl4(s, dt) {
  const A = [[0.25, 0.25 - SQ3_6], [0.25 + SQ3_6, 0.25]];
  let k1 = f(s), k2 = f(s);
  for (let it = 0; it < 24; it++) {
    const Y1 = [0, 0, 0, 0], Y2 = [0, 0, 0, 0];
    for (let j = 0; j < 4; j++) {
      Y1[j] = s[j] + dt * (A[0][0] * k1[j] + A[0][1] * k2[j]);
      Y2[j] = s[j] + dt * (A[1][0] * k1[j] + A[1][1] * k2[j]);
    }
    const n1 = f(Y1), n2 = f(Y2);
    let d = 0;
    for (let j = 0; j < 4; j++) d = Math.max(d, Math.abs(n1[j] - k1[j]), Math.abs(n2[j] - k2[j]));
    k1 = n1; k2 = n2;
    if (d < 1e-13) break;
  }
  return [0, 1, 2, 3].map(j => s[j] + dt * 0.5 * (k1[j] + k2[j]));
}
const s0 = [0.288, 0, -0.840, 1.704];
for (const [name, mth] of [['RK4', rk4], ['GL4', gl4]]) {
  for (const dt of [0.002, 0.005, 0.01]) {
    let s = s0.slice(), minM = 9, tM = 0, minE = 9, escapeT = null;
    const path = [];
    for (let i = 0; i < 30 / dt; i++) {
      s = mth(s, dt);
      const dM = Math.hypot(s[0] - 1 + MU, s[1]), dE = Math.hypot(s[0] + MU, s[1]), R = Math.hypot(s[0], s[1]);
      if (dM < minM) { minM = dM; tM = (i + 1) * dt; }
      minE = Math.min(minE, dE);
      if (R > 3.5 && escapeT === null) escapeT = (i + 1) * dt;
      if (i % Math.round(0.5 / dt) === 0 && path.length < 60) path.push(`(${s[0].toFixed(2)},${s[1].toFixed(2)})`);
      if (!Number.isFinite(s[0]) || R > 6) break;
    }
    console.log(`${name} dt=${dt}: minM=${minM.toFixed(5)} (t=${tM.toFixed(1)})  minE=${minE.toFixed(4)}  escape t=${escapeT ? escapeT.toFixed(1) : '-'}`);
    if (dt === 0.005 && name === 'RK4') console.log('  path:', path.join(' '));
  }
}
// 地月圆轨道 vy 精确值
const vC = Math.sqrt((1 - MU) / 0.15), x0 = -MU - 0.15;
console.log('\n绕地预设: x0=', x0.toFixed(9), ' vy0=(精确)', (vC - x0).toFixed(9));
// L4 预设 RK4 检查
const L4 = [0.5 - MU, Math.sqrt(3) / 2];
let s = [L4[0] + 0.02, L4[1], 0, 0];
let maxd = 0;
for (let i = 0; i < 100 / 0.005; i++) { s = rk4(s, 0.005); maxd = Math.max(maxd, Math.hypot(s[0] - L4[0], s[1] - L4[1])); }
console.log('L4+0.02 RK4 t=100 max d(L4)=', maxd.toFixed(3));

// 引力辅助预设：直接构造近月双曲线飞掠，要求对步长稳健
const MU = 0.0121505856;
const RM = 1737.4 / 384400;
function omega(x, y) {
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  return 0.5 * (x * x + y * y) + (1 - MU) / r1 + MU / r2;
}
function f(s) {
  const [x, y, vx, vy] = s;
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  const r1c = r1 ** 3, r2c = r2 ** 3;
  return [vx, vy, 2 * vy + x - (1 - MU) * (x + MU) / r1c - MU * (x - 1 + MU) / r2c,
    -2 * vx + y - (1 - MU) * y / r1c - MU * y / r2c];
}
const add = (s, k, h) => [s[0] + h * k[0], s[1] + h * k[1], s[2] + h * k[2], s[3] + h * k[3]];
function rk4(s, dt) {
  const k1 = f(s), k2 = f(add(s, k1, dt / 2)), k3 = f(add(s, k2, dt / 2)), k4 = f(add(s, k3, dt));
  return [0, 1, 2, 3].map(j => s[j] + dt / 6 * (k1[j] + 2 * k2[j] + 2 * k3[j] + k4[j]));
}
function fly(s0, dt, tMax) {
  let s = s0.slice(), minM = 9, tM = 0, minE = 9, endR = 0, tEnd = 0;
  for (let i = 0; i < tMax / dt; i++) {
    s = rk4(s, dt); tEnd = (i + 1) * dt;
    const dM = Math.hypot(s[0] - 1 + MU, s[1]);
    if (dM < minM) { minM = dM; tM = tEnd; }
    minE = Math.min(minE, Math.hypot(s[0] + MU, s[1]));
    endR = Math.hypot(s[0], s[1]);
    if (!Number.isFinite(s[0]) || endR > 4) break;
  }
  return { minM, tM, minE, endR, tEnd, s };
}
const MX = 1 - MU, MY = 0;
const res = [];
for (let ia = 0; ia < 48; ia++) {
  const a = ia * Math.PI / 24;
  for (const d of [0.35, 0.45]) {
    const px = MX + d * Math.cos(a), py = MY + d * Math.sin(a);
    if (Math.hypot(px + MU, py) < 0.25) continue; // 别贴着地球
    for (const V of [0.35, 0.5, 0.7]) {
      for (const b of [-0.05, -0.035, -0.02, 0.02, 0.035, 0.05]) {
        // 瞄准点 = 月心 + b·(垂直于接近方向)
        const ux = (MX - px) / d, uy = (MY - py) / d; // 接近方向单位向量
        const tx = MX - b * uy, ty = MY + b * ux;     // 瞄准点
        let dx = tx - px, dy = ty - py; const L = Math.hypot(dx, dy);
        const s0 = [px, py, V * dx / L, V * dy / L];
        const A = fly(s0, 0.005, 20), B = fly(s0, 0.002, 20);
        if (A.minM < 0.1 && A.endR > 1.8 && A.minM > 0.008 && B.minM > 0.008 && B.endR > 1.8
          && Math.abs(A.minM - B.minM) < 0.01 && A.minE > 0.12 && A.tM < 12) {
          // 惯性系能量变化
          const Ein = s => { const vix = s[2] - s[1], viy = s[3] + s[0]; return 0.5 * (vix * vix + viy * viy) - omega(s[0], s[1]); };
          const E0 = Ein(s0), E1 = Ein(A.s);
          res.push({ a: a.toFixed(2), d, V, b, x: px.toFixed(3), y: py.toFixed(3), vx: s0[2].toFixed(3), vy: s0[3].toFixed(3), minM: +A.minM.toFixed(4), tM: +A.tM.toFixed(1), endR: +A.endR.toFixed(2), tEnd: +A.tEnd.toFixed(1), dEin: +(E1 - E0).toFixed(3) });
        }
      }
    }
  }
}
res.sort((p, q) => q.dEin - p.dEin);
console.log(`稳健候选 ${res.length} 个（按 ΔE_in 降序 前 20）:`);
console.table(res.slice(0, 20));

// 精评候选：正确惯性系能量、路径形状、RK4/GL4 × dt 稳健性
const MU = 0.0121505856;
const RM = 1737.4 / 384400;
function omega(x, y) {
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  return 0.5 * (x * x + y * y) + (1 - MU) / r1 + MU / r2;
}
function f(s) {
  const [x, y, vx, vy] = s;
  const r1 = Math.hypot(x + MU, y), r2 = Math.hypot(x - 1 + MU, y);
  return [vx, vy, 2 * vy + x - (1 - MU) * (x + MU) / r1 ** 3 - MU * (x - 1 + MU) / r2 ** 3,
    -2 * vx + y - (1 - MU) * y / r1 ** 3 - MU * y / r2 ** 3];
}
const add = (s, k, h) => [s[0] + h * k[0], s[1] + h * k[1], s[2] + h * k[2], s[3] + h * k[3]];
function rk4(s, dt) {
  const k1 = f(s), k2 = f(add(s, k1, dt / 2)), k3 = f(add(s, k2, dt / 2)), k4 = f(add(s, k3, dt));
  return [0, 1, 2, 3].map(j => s[j] + dt / 6 * (k1[j] + 2 * k2[j] + 2 * k3[j] + k4[j]));
}
const SQ3_6 = Math.sqrt(3) / 6;
function gl4(s, dt) {
  const A = [[0.25, 0.25 - SQ3_6], [0.25 + SQ3_6, 0.25]];
  let k1 = f(s), k2 = f(s);
  for (let it = 0; it < 24; it++) {
    const Y1 = [0, 0, 0, 0], Y2 = [0, 0, 0, 0];
    for (let j = 0; j < 4; j++) { Y1[j] = s[j] + dt * (A[0][0] * k1[j] + A[0][1] * k2[j]); Y2[j] = s[j] + dt * (A[1][0] * k1[j] + A[1][1] * k2[j]); }
    const n1 = f(Y1), n2 = f(Y2);
