    const allFinite = [...c1, ...c2, ...c3].every(Number.isFinite);
    const ok = allFinite && c1.length > 0 && c2.length === 0 && c3.length > 0;
    return {pass: ok, detail: `C=C(L1)+0.002: ${c1.length / 4} 段；C=2.50（应全域允许）: ${c2.length / 4} 段；C=C(L4)+0.05: ${c3.length / 4} 段；坐标全部有限=${allFinite}`};
