/** 重建给定 C 的线段与禁止区域填充（2Ω < C ⇔ Ω < C/2 为禁区） */
rebuild(C) {
  this.builtC = C;
  this.segs = this.contour(C / 2);
  const {nx, ny, grid, PW, PH, offCtx} = this;
  const cw = PW / (nx - 1), ch = PH / (ny - 1);
  offCtx.clearRect(0, 0, PW, PH);
  offCtx.fillStyle = 'rgba(78,120,210,.25)';
  const level = C / 2;
  for (let j = 0; j < ny - 1; j++) for (let i = 0; i < nx - 1; i++) {
    const a = grid[j * nx + i], b = grid[j * nx + i + 1], c = grid[(j + 1) * nx + i + 1], d = grid[(j + 1) * nx + i];
    if (a < level && b < level && c < level && d < level)
      offCtx.fillRect(i * cw, PH - (j + 1) * ch, cw + 0.5, ch + 0.5);  // 像素行翻转到物理 y 向上
  }
}

input.new_string:
/** 重建给定 C 的线段与禁止区域填充（2Ω < C ⇔ Ω < C/2 为禁区）
 *  填充用与 marching squares 同源的单元格多边形裁剪，边缘与等值线严格一致（无锯齿） */
rebuild(C) {
  this.builtC = C;
  const level = C / 2;
  this.segs = this.contour(level);
  const {nx, ny, grid, x0, y0, PW, PH, offCtx} = this;
  const dx = (this.x1 - x0) / (nx - 1), dy = (this.y1 - y0) / (ny - 1);
  const px = x => (x - x0) / (this.x1 - x0) * PW;      // 物理 → 离屏像素
  const py = y => (this.y1 - y) / (this.y1 - y0) * PH;  // 注意 y 翻转
  offCtx.clearRect(0, 0, PW, PH);
  offCtx.fillStyle = 'rgba(78,120,210,.25)';
  offCtx.beginPath();
  for (let j = 0; j < ny - 1; j++) for (let i = 0; i < nx - 1; i++) {
    const va = grid[j * nx + i], vb = grid[j * nx + i + 1],
          vc = grid[(j + 1) * nx + i + 1], vd = grid[(j + 1) * nx + i];
    const bA = va < level, bB = vb < level, bC = vc < level, bD = vd < level;
    const m = (bA ? 1 : 0) | (bB ? 2 : 0) | (bC ? 4 : 0) | (bD ? 8 : 0);
    if (m === 0) continue;
    const xa = x0 + i * dx, xb = x0 + (i + 1) * dx, ya = y0 + j * dy, yb = y0 + (j + 1) * dy;
    if (m === 15) {   // 整格都在禁区内：快速路径
      offCtx.rect(px(xa), py(yb), px(xb) - px(xa) + 0.7, py(ya) - py(yb) + 0.7);
      continue;
    }
    // 混合格：取「低于 level 的角点 + 各边交点」按绕格顺序连线，即格内禁区多边形
    const poly = [];
    const cross = (below1, v1, v2, x1_, y1_, x2_, y2_) => {
      if (below1 === (v1 < level)) return null;   // 该边无符号变化
      const t = (level - v1) / (v2 - v1);
      return [x1_ + t * (x2_ - x1_), y1_ + t * (y2_ - y1_)];
    };
    // 绕格顺序：a → 底边 → b → 右边 → c → 顶边 → d → 左边
    if (bA) poly.push([xa, ya]);
    let p = cross(bA, va, vb, xa, ya, xb, ya); if (p) poly.push(p);
    if (bB) poly.push([xb, ya]);
    p = cross(bB, vb, vc, xb, ya, xb, yb); if (p) poly.push(p);
    if (bC) poly.push([xb, yb]);
    p = cross(bD, vd, vc, xa, yb, xb, yb); if (p) poly.push(p);   // 顶边按 d→c 方向
    if (bD) poly.push([xa, yb]);
    p = cross(bA, va, vd, xa, ya, xa, yb); if (p) poly.push(p);
    if (poly.length >= 3) {
      offCtx.moveTo(px(poly[0][0]), py(poly[0][1]));
      for (let k = 1; k < poly.length; k++) offCtx.lineTo(px(poly[k][0]), py(poly[k][1]));
      offCtx.closePath();
    }
  }
  offCtx.fill();
}

