{
  name: '零速度曲线完整性（marching squares）',
  async run() {
    // contour(level) 的参数是 Ω 等值线 level = C/2（禁区为 Ω < C/2）
    const c1 = ZVC.contour((LPTS.L1.C + 0.002) / 2);   // 颈口刚开：两主天体周围各有闭合禁区
    const c2 = ZVC.contour(2.5 / 2);                    // C=2.5 < 2·Ωmin：全域允许，应无曲线
    const c3 = ZVC.contour((LPTS.L4.C + 0.05) / 2);     // C 略高于 C(L4)：L4/L5 周围出现允许孤岛
    const allFinite = [...c1, ...c2, ...c3].every(Number.isFinite);
    const ok = allFinite && c1.length > 0 && c2.length === 0 && c3.length > 0;
    return {pass: ok, detail: `C=C(L1)+0.002: ${c1.length / 4} 段；C=2.50（应全域允许）: ${c2.length / 4} 段；C=C(L4)+0.05: ${c3.length / 4} 段；坐标全部有限=${allFinite}`};
  }
},

