/** 重建给定 C 的线段与禁止区域填充（2Ω < C ⇔ Ω < C/2 为禁区） */
rebuild(C) {
  this.builtC = C;
  this.segs = this.contour(C / 2);
  const {nx, ny, grid, PW, PH, offCtx} = this;
  const cw = PW / (nx - 1), ch = PH / (ny - 1);
  offCtx.clearRect(0, 0, PW, PH);
  offCtx.fillStyle = 'rgba(78,120,210,.25)';
  const level = C / 2;
  for (let j = 0; j < ny - 1; j++) for (let i = 0; i < nx - 1; i++) {
    const a = grid[j * nx + i], b = grid[j * nx + i + 1], c = grid[(j + 1) * nx + i + 1], d = grid[(j + 1) * nx + i];
    if (a < level && b < level && c < level && d < level)
      offCtx.fillRect(i * cw, PH - (j + 1) * ch, cw + 0.5, ch + 0.5);  // 像素行翻转到物理 y 向上
  }
}

